import json
from pathlib import Path
p=Path('/workspace/sites/olympiad-atlas');new=[]
def add(y,n,r,t,tags,s,reason,shared=None,solution=None):
 url=f'https://web.evanchen.cc/exams/JMO-{y}-notes.pdf';apps=[dict(competition='USAJMO',year=y,number=str(n))]
 if shared:apps.append(dict(competition='USAMO',year=y,number=str(shared)))
 new.append(dict(id=f'us-usajmo-{y}-{n}',country='United States',competition='USAJMO',year=y,number=str(n),statement=s,solution=solution or f'[View Evan Chen’s worked solution notes]({url}).',sourceUrl=url,solutionUrl=url,solutionKind='original-exposition' if solution else 'source-link',topic=t,tags=tags.split('|'),difficulty=r,ratingReason=reason,reviewStatus='individually-assessed',notes='Statement restated in original wording. Mathematical argument individually checked; linked author-maintained notes are not labelled official.',appearances=apps))
add(2017,1,4.5,'Number theory','Constructions|Binomial theorem|Powers of two',r'Prove that infinitely many pairs of coprime integers $a,b>1$ satisfy $a+b\mid a^b+b^a$.','A useful family consists of the two odd neighbours of a power of 2. Their sum is another power of 2, and truncating the binomial expansions modulo that sum proves divisibility. Finding the family is the non-routine part.',shared=1,solution=r'For every integer $r\ge2$, set $a=2^r-1$ and $b=2^r+1$. Their gcd divides $2$ and both are odd, so they are coprime. Modulo $2^{r+1}$, all binomial terms involving $(2^r)^2$ vanish. Since $a,b$ are odd, $a^b\equiv-1+b2^r$ and $b^a\equiv1+a2^r$. Their sum is congruent to $(a+b)2^r\equiv0\pmod{a+b}$. The pairs are distinct and both entries exceed $1$.')
add(2017,2,5.5,'Number theory','Diophantine equations|GCD|Valuations',r'Find all positive integer solutions of $(3x^3+xy^2)(x^2y+3y^3)=(x-y)^7$, and in particular prove that there are infinitely many.','Divide out the gcd and compare the remaining factors with the seventh power of the difference. Coprimality eliminates all odd prime divisors of that difference; an exact 2-adic count excludes the even case. The resulting consecutive parameters give the full family.')
add(2017,3,6,'Geometry','Ptolemy theorem|Area|Similarity',r'Let $P$ lie on the circumcircle of equilateral triangle $ABC$, distinct from its vertices. Put $D=PA\cap BC$, $E=PB\cap CA$, and $F=PC\cap AB$, using full lines. Prove $[DEF]=2[ABC]$.','Ptolemy relates the three distances from P, while similar triangles express the distances to D,E,F as quotients of those lengths. Splitting DEF into three triangles around P then makes the area identity collapse. Discovering this coordinated length calculation requires several linked ideas.')
add(2017,4,6.5,'Number theory','Primes|Difference of squares|Bounds|Case analysis',r'Do positive integers $a,b,c$ exist for which $p=(a-2)(b-2)(c-2)+12$ is prime and is a proper divisor of the positive integer $a^2+b^2+c^2+abc-2017$? Give a proof.','Shifting each variable by 2 reveals a difference of squares modulo p. Its two linear factors must then be bounded against the cubic expression for p. Small and negative shifted values need careful separate treatment before the final contradiction works.')
add(2017,5,6,'Geometry','Arc midpoints|Reflections|Power of a point',r'In acute triangle $ABC$, let $O,H$ be the circumcentre and orthocentre. Let $M$ be the midpoint of $BC$, and let $D\in BC$ satisfy $\angle BAD=\angle CAD$. Ray $MO$ meets circle $BHC$ at $N$. Prove $\angle ADO=\angle HAN$.','Reflecting the relevant arc midpoint across BC identifies N, converting the orthocentre construction into a circumcircle configuration. A power identity then proves ADNO cyclic, after which the desired angle follows. Identifying the reflected point is the main obstacle.')
add(2017,6,5.5,'Combinatorics','Adjacent swaps|Greedy matching|Invariants',r'Place $n$ red and $n$ blue distinct points on a circle, none at a fixed marked point $Z$. Choose any order $R_1,\ldots,R_n$ of the red points. In turn match $R_i$ to the first still-unmatched blue point encountered counterclockwise from it. Prove that the number of resulting counterclockwise matching arcs that contain $Z$ is independent of the chosen red order.','Compare orders differing by an adjacent swap. Only two matches change, and the few possible circular arrangements preserve the number of arcs over every point. Recognising that local comparison suffices is the central idea.',shared=4)
add(2016,1,5.5,'Geometry','Incentres|Arc midpoints|Fixed points|Congruence',r'Triangle $ABC$ is inscribed in $\omega$ and has $AB=AC$. A point $P$ varies on the open arc $BC$ not containing $A$. Let $I_B,I_C$ be the incentres of $ABP,ACP$. Prove that circle $PI_BI_C$ always passes through one fixed point.','The fixed point is suggested by the symmetry. Extending the two angle bisectors to the original circle gives arc midpoints and two congruent triangles; equal distances then establish the required cyclicity. The location of P on the specified arc matters.')
add(2016,2,5.5,'Number theory','Euler theorem|Decimal digits|Chinese remainder theorem',r'Prove that some positive integer $n<10^6$ has the property that the decimal expansion of $5^n$ contains six consecutive zeros.','Force the last twenty digits to agree with a much smaller power of 5, padded with zeros. Euler’s theorem modulo a power of 2 combines with automatic divisibility by a power of 5; selecting compatible exponent and digit bounds is the key construction.')
add(2016,3,7,'Combinatorics','Extremal sets|Inductive constructions|Counting',r'The $100$ distinct nonempty subsets $X_1,\ldots,X_{100}$ of a finite set $S$ satisfy $X_i\cap X_{i+1}=\varnothing$ and $X_i\cup X_{i+1}\ne S$ for $1\le i<100$. Find the least possible $|S|$.','A size-class count rules out seven elements by bounding how many large sets can be separated by small ones. Attaining eight requires a nontrivial recursive construction that doubles a chain while preserving disjointness, noncoverage, and distinctness.',shared=1)
add(2016,4,4,'Combinatorics','Pigeonhole principle|Extremal constructions|Pairing',r'Find the least integer $N$ such that, after any $2016$ numbers are deleted from $\{1,2,\ldots,N\}$, one can choose $2016$ distinct remaining numbers whose sum is $N$.','Deleting the smallest numbers gives the sharp lower bound. For the matching upper bound, form disjoint pairs with a common sum; even the worst deletions leave enough intact pairs. Choosing the pairing range is the main step.')
add(2016,5,5.5,'Geometry','Cyclic quadrilaterals|Power of a point|Perpendicularity',r'Let $O$ be the circumcentre of acute triangle $ABC$, and let $H$ be the perpendicular foot from $A$ to $BC$. Drop perpendiculars from $H$ to $AB,AC$, meeting them at $P,Q$. If $AH^2=2AO^2$, prove that $O,P,Q$ are collinear.','The projection products first show PQCB is cyclic, identifying the direction of PQ relative to AO. Adding the point opposite A on the circumcircle supplies a second power relation; the given squared-length condition then fixes the intersection at O.')
add(2016,6,7,'Algebra','Functional equations|Zero propagation|Positivity',r'Find all functions $f:\mathbb R\to\mathbb R$ satisfying $(f(x)+xy)f(x-3y)+(f(y)+xy)f(3x-y)=f(x+y)^2$ for all real $x,y$.','Basic substitutions give evenness and a pointwise alternative, but do not classify the function. One must prove zeros propagate under doubling, obtain a quadratic-or-zero dichotomy, and then use a positive-coefficient substitution to eliminate mixtures. This sustained chain reaches the upper edge.',shared=4)
add(2015,1,5.5,'Combinatorics','Averaging|Constructions|Symmetry',r'A move on a finite real sequence replaces two selected terms by their arithmetic mean. Construct $2015$ distinct real numbers such that, whatever first move is made, some finite continuation of moves makes all the terms equal.','Start with a symmetric arithmetic progression. A first move away from the centre can be repaired using the opposite pair; a move involving the centre needs one extra opposite pair. Designing and checking that exceptional repair is the principal difficulty.')
add(2015,2,5.5,'Number theory','Diophantine equations|Factorisation|Parametrisation',r'Find all integer pairs $(x,y)$ such that $x^2+xy+y^2=\left((x+y)/3+1\right)^3$.','Sum-and-difference variables expose a square, and integrality forces the sum to be a multiple of 3. The resulting cubic factorises as a square times a linear expression. Parameterising that last square and checking parity completes an infinite family.',shared=1)
add(2015,3,6.5,'Geometry','Loci|Nine-point circle|Homothety|Power of a point',r'Quadrilateral $APBQ$ is inscribed in circle $\omega$, with $\angle APB=\angle AQB=90^\circ$ and $AP=AQ<BP$. Let $X$ vary on segment $PQ$, and let $AX$ meet $\omega$ again at $S$. Choose $T$ on arc $AQB$ such that $XT\perp AX$. Prove that the midpoint $M$ of $ST$ always lies on a fixed circle.','The nine-point circle of AST has fixed radius and fixed power from A, so its centre has a circular locus. Two homotheties through the Euler line and centroid transfer that locus to M. Discovering this auxiliary centre is the substantial geometric step.',shared=2)
add(2015,4,4.5,'Algebra','Functional equations|Arithmetic progressions|Rational numbers',r'Find all functions $f:\mathbb Q\to\mathbb Q$ such that $f(x)+f(t)=f(y)+f(z)$ whenever $x<y<z<t$ are rational numbers in arithmetic progression.','Combine two overlapping four-term progressions to derive the three-term midpoint identity. On each rational grid this forces a constant first difference, and common denominators identify one affine function. The main insight is the overlapping progression choice.')
add(2015,5,5.5,'Geometry','Sine rule|Cyclic quadrilaterals|Isogonal lines',r'For cyclic quadrilateral $ABCD$, prove these conditions are equivalent: there exists $X\in BD$ with $\angle BAC=\angle XAD$ and $\angle BCA=\angle XCD$; there exists $Y\in AC$ with $\angle CBD=\angle YBA$ and $\angle CDB=\angle YDA$.','Apply the sine rule to the two triangles on either side of a diagonal. The two angle requirements force reciprocal expressions for the same division ratio, so both existence statements reduce to the same opposite-side product identity. This gives a short synthetic route without specialized terminology.',solution=r'''Write $a=AB$, $b=BC$, $c=CD$, $d=DA$. The ray from $A$ satisfying the first angle condition meets the interior of $BD$ at a unique point, and the sine rule gives
$$\frac{BX}{XD}=\frac{AB\sin\angle BAX}{AD\sin\angle XAD}=\frac{ac}{bd}.$$
Here $\angle BAX=\angle CAD$, and the cyclic quadrilateral converts the sines into the corresponding chord lengths. The condition from $C$ similarly gives $BX/XD=bd/(ac)$. Thus the two rays meet at the same point of $BD$ exactly when $ac=bd$; in that case $X$ is its midpoint.

For the rays from $B,D$ in the second condition, the same sine-rule calculation gives respectively $AY/YC=ac/(bd)$ and $AY/YC=bd/(ac)$. Their intersection lies on $AC$ exactly under the same condition $ac=bd$. Therefore the two existence statements are equivalent.''')
add(2015,6,6,'Combinatorics','Invariants|Equivalence classes|Stars and bars|Permutations',r'Distribute $m\ge1$ identical stones among the cells of an $n\times n$ grid. A move chooses a rectangle of cells, removes one stone from each of one pair of opposite corners, and adds one to each of the other pair. Only moves that leave nonnegative piles are allowed. Two distributions are equivalent if a sequence of moves connects them. How many equivalence classes are there?','Row and column totals are invariants, but a full solution must prove they are complete invariants. Treat stones as coordinate pairs: rectangle moves exchange second coordinates, giving the needed reachability. Counting the possible margins then uses stars and bars.',shared=4)
data=json.loads((p/'data/americas.json').read_text());ids={x['id'] for x in new};data=[x for x in data if x['id'] not in ids]+new
(p/'data/americas.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
c=json.loads((p/'research/americas-coverage.json').read_text());full={2017:[4.5,5.5,6,6.5,6,5.5],2016:[5.5,5.5,7,4,5.5,7],2015:[5.5,5.5,6.5,4.5,5.5,6]}
c['fullyScreened']=[x for x in c['fullyScreened'] if not(x['competition']=='USAJMO' and x['year'] in full)]
c['partiallyScreened']=[x for x in c['partiallyScreened'] if not(x['competition']=='USAJMO' and x['year'] in full)]
for year,ratings in full.items():c['fullyScreened'].append(dict(competition='USAJMO',year=year,ratings=ratings,source=f'https://web.evanchen.cc/exams/JMO-{year}-notes.pdf'))
for year,ratings in {2017:{'1':4.5,'4':5.5},2016:{'1':7,'4':7},2015:{'1':5.5,'2':6.5,'4':6}}.items():
 old=next((x for x in c['partiallyScreened'] if (x['competition'],x['year'])==('USAMO',year)),None)
 if old:old['ratings'].update(ratings)
 else:c['partiallyScreened'].append(dict(competition='USAMO',year=year,ratings=ratings,pending=[str(i) for i in range(1,7) if str(i) not in ratings]))
c['papersScreened']=len(c['fullyScreened']);c['problemAppearancesScreened']=sum(len(x['ratings']) for x in c['fullyScreened']+c['partiallyScreened']);c['uniqueIncluded']=len(data)
c['gaps'][1]='US: USAJMO 2015–2026 fully screened; earlier USAJMO years pending except listed entries. USAMO 2006–2014 screening and recent selected/shared problems are listed individually; outstanding problems and other years remain pending.'
(p/'research/americas-coverage.json').write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n');print('Total',len(data))
